public:
    bool canMakeSubsequence(string str1, string str2) {
        int i = 0, j = 0, n = str1.size(), m = str2.size();
        while (i < n && j < m) {
            char c1 = str1[i], c2 = str2[j];
            char nxt = (c1 - 'a' + 1) % 26 + 'a';
            if (c1 == c2 || nxt == c2) j++;
            i++;
        }
