class Solution {
    public boolean canMakeSubsequence(String str1, String str2) {
        int i = 0, j = 0, n = str1.length(), m = str2.length();
        while (i < n && j < m) {
            char c1 = str1.charAt(i), c2 = str2.charAt(j);
            char nxt = (char) ((c1 - 'a' + 1) % 26 + 'a');
            if (c1 == c2 || nxt == c2) j++;
            i++;
        }
        return j == m;
    }
}

