var canMakeSubsequence = function(str1, str2) {
    let i = 0, j = 0, n = str1.length, m = str2.length;
    while (i < n && j < m) {
        const code1 = str1.charCodeAt(i) - 97;
        const code2 = str2.charCodeAt(j) - 97;
        const nxt = (code1 + 1) % 26;
        if (code1 === code2 || nxt === code2) j++;
        i++;
    }
    return j === m;
};
